//! Actual account creation/replace, owned bootstrap, same authenticated session and SQL.
use super::*;
use n::group_owner_only_test_support::{self as support,Flow};
async fn run_case(flow:Flow){
 let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let cfg=serde_json::from_value(support::account_json(&cert.root,port)).unwrap();let line=manager.create(cfg,100).await.unwrap().account.line_id;let(tx,rx)=tokio::sync::oneshot::channel();let peer=tokio::spawn(Box::pin(support::serve(listener,cert.server_config(&TLS13),temp.database.clone(),line.clone(),flow,rx)));
 bounded(manager.start(&line,1,100)).await.unwrap();phase(&manager,&line,"hosted").await;let installed=manager.get(&line,100).await.unwrap().group_owner_only_supported;assert_eq!(installed,Some(flow!=Flow::NoReference));let read=flow!=Flow::ConfirmOnly;
 let prepare=||manager.prepare_owner_only_group(&line,1,"private-single-group",1,&[],NONCE,true,true,true,read);
 if flow==Flow::NoReference{assert_eq!(prepare().err(),Some("app_account_group_owner_only_not_installed"));assert!(manager.relation_intent_history(&line,128).unwrap().is_empty());}else{
  let p=prepare().unwrap();let intents=manager.relation_intent_history(&line,128).unwrap();assert_eq!(intents[0].state,"preparing");assert_eq!(intents[0].management.as_ref().unwrap().operation,"create_owner_only");assert_eq!(manager.prepare_group_create(&line,1,"name",1,b"fixture-user",&[Relation{label:b"fixture-user",flags:0,first:b"given",second:b"",properties:vec![]}],&[],NEXT,true,true,false).err(),Some("app_account_relation_preparing"));
  if flow==Flow::NoWrite{drop(p);assert!(manager.relation_write_history(&line,128).unwrap().is_empty());assert_eq!(manager.relation_intent_history(&line,128).unwrap()[0].state,"not_sent");}else{let v=bounded(manager.finish_group_create(p)).await.unwrap();assert_eq!(v.write.state,if flow==Flow::Reject{"rejected"}else{"confirmed"});assert_eq!(v.write.management.as_ref().unwrap().operation,"create_owner_only");assert_eq!(v.properties_read.state,match flow{Flow::ConfirmRead=>"observed",Flow::ConfirmOnly=>"not_requested",_=>"not_attempted"});let repeated=bounded(manager.finish_group_create(prepare().unwrap())).await.unwrap();assert_eq!(repeated.write.id,v.write.id);assert_eq!(repeated.properties_read.state,if read{"not_attempted"}else{"not_requested"});assert_eq!(rows(&temp.database,&line),1);}
 }
 no_other_business(&manager,&temp.database,&line);tx.send(()).unwrap();assert!(!bounded(manager.stop(&line,1,100)).await.unwrap().io_cleanup_required);bounded(peer).await.unwrap();released(&temp.database,&line);
}
#[tokio::test]async fn owner_only_account_derived_login_and_exact_uid_then_optional_read_no_resolver_dial(){Box::pin(run_case(Flow::ConfirmRead)).await;}
#[tokio::test]async fn owner_only_account_no_read_consent_and_nonce_replay_do_not_dial_or_read(){Box::pin(run_case(Flow::ConfirmOnly)).await;}
#[tokio::test]async fn owner_only_account_rejected_create_never_gets_current_read_receipt(){Box::pin(run_case(Flow::Reject)).await;}
#[tokio::test]async fn owner_only_account_absent_matched_userentry_prevents_even_preparing(){Box::pin(run_case(Flow::NoReference)).await;}
#[tokio::test]async fn owner_only_account_dropping_prepared_input_is_not_sent_and_unblocks_without_rpc(){Box::pin(run_case(Flow::NoWrite)).await;}
#[tokio::test]async fn owner_only_profile_is_independent_and_optional_migration_keeps_previous_accounts(){
 let cert=Certificates::generate("IP:127.0.0.1");let t=TempDatabase::new();let m=AccountManager::new(t.database.clone());let enabled=support::account_json(&cert.root,1);let mut old=enabled.clone();old["profile"].as_object_mut().unwrap().remove("group_owner_only");let old:AccountConfig=serde_json::from_value(old).unwrap();let raw=old.encode_private().unwrap();assert!(!String::from_utf8_lossy(&raw).contains("group_owner_only"));assert_eq!(AccountConfig::decode_private(&raw).unwrap().encode_private().unwrap(),raw);let line=m.create(old,100).await.unwrap().account.line_id;
 let cols=||t.database.with_conn(|c|c.query_row("SELECT count(*) FROM pragma_table_info('app_voice_group_creations') WHERE name IN ('owner_only','owner_only_hash')",[],|r|r.get::<_,usize>(0)).map_err(|_|"fixture")).unwrap();assert_eq!(cols(),0);for mode in 0..3{let mut v=enabled.clone();match mode{0=>v["profile"]["group_owner_only"]["from_session"]=serde_json::json!(false),1=>v["profile"]["group_creation"]=serde_json::Value::Null,_=>v["profile"]["gateway_uri"]=serde_json::json!("caller-supplied-uri")};let cfg:AccountConfig=serde_json::from_value(v).unwrap();assert!(cfg.runtime_profile().is_err());}m.replace(&line,1,serde_json::from_value(enabled).unwrap(),100).await.unwrap();assert_eq!(cols(),2);assert_eq!(m.get(&line,100).await.unwrap().phase,"stopped");
}
